(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"data":{"h":"WHAT YOU ARE LOOKING AT","t":"**Four data points.** No single straight line passes through all of them, so we must decide what “best fit” means."},"candidate-line":{"h":"TRY A CANDIDATE LINE","t":"Pick a line, here **y = 0.5x + 2**, and see how well it predicts each point."},"residuals":{"h":"MEASURE EACH RESIDUAL","t":"A **residual** is the vertical gap between a point and the line: **actual minus predicted**. The bars show how far the line misses each point."},"square-errors":{"h":"SQUARE THE RESIDUALS","t":"Squaring makes every error **positive** and **punishes big misses**. Adding the squares gives a total of **2.5** for this line."},"compare-lines":{"h":"COMPARE OTHER LINES","t":"Try other lines. **Each one has its own total of squared errors**, so lines can be ranked by how well they fit."},"minimum":{"h":"THE BEST LINE HAS THE SMALLEST TOTAL","t":"**Least squares** picks the line with the smallest total squared error. Here that is **y = 0.8x + 1.5**, with a total of **1.8**."},"projection-view":{"h":"THE SAME ANSWER, AS A PROJECTION","t":"Geometrically, the data vector **b** is **projected** onto the space of possible predictions **A x**. The leftover residual is **perpendicular** to that space."},"ml-connection":{"h":"TAKEAWAY","t":"Fitting a regression line is exactly this problem. The best x solves **AᵀA x = Aᵀb**, the **normal equations**."}};
  // ── scene ──
  var steps = [
    { id: "data", label: "Data that no line fits perfectly", caption: "Four data points. No single straight line passes through all of them." },
    { id: "candidate-line", label: "Try a candidate line", caption: "Pick a line, here y = 0.5x + 2, and see how well it predicts each point." },
    { id: "residuals", label: "Measure each residual", caption: "A residual is the vertical gap between a point and the line: actual minus predicted." },
    { id: "square-errors", label: "Square the residuals", caption: "Squaring makes every error positive and punishes big misses. Add the squares: here the total is 2.5." },
    { id: "compare-lines", label: "Compare other lines", caption: "Try other lines. Each one has its own total of squared errors." },
    { id: "minimum", label: "The best line has the smallest total", caption: "Least squares picks the line with the smallest total squared error. Here that is y = 0.8x + 1.5, with 1.8." },
    { id: "projection-view", label: "The same answer, as a projection", caption: "Geometrically, the data vector b is projected onto the space of predictions A x. The residual is perpendicular to that space." },
    { id: "ml-connection", label: "This is linear regression", caption: "Fitting a regression line is exactly this problem. The best x solves AᵀA x = Aᵀb, the normal equations." }
  ];

  var PTS = [[1, 2], [2, 3], [3, 5], [4, 4]];
  var LINES = [
    { m: 0.5, b: 2, color: "#e2b44a", key: "y", name: "y = 0.5x + 2" },
    { m: 1, b: 1, color: "#38bdf8", key: "b", name: "y = x + 1" },
    { m: 0.8, b: 1.5, color: "#f472b6", key: "p", name: "y = 0.8x + 1.5" }
  ];
  function sse(l) {
    return PTS.reduce(function (s, p) { var r = p[1] - (l.m * p[0] + l.b); return s + r * r; }, 0);
  }
  function PX(x) { return 70 + 100 * x; }
  function PY(y) { return 300 - 48 * y; }

  var plot = el("g", {}, svg);
  el("line", { x1: PX(0), y1: PY(0), x2: PX(5.3), y2: PY(0), class: "axis" }, plot);
  el("line", { x1: PX(0), y1: PY(0), x2: PX(0), y2: PY(5.6), class: "axis" }, plot);
  txt(plot, PX(5.3), PY(0) + 16, "tick", "x", "end");
  txt(plot, PX(0) - 8, PY(5.6) + 4, "tick", "y", "end");

  var lineEls = LINES.map(function (l) {
    return el("line", { x1: PX(0.3), y1: PY(l.m * 0.3 + l.b), x2: PX(5), y2: PY(l.m * 5 + l.b), stroke: l.color, "stroke-width": 3, "stroke-linecap": "round", opacity: 0 }, plot);
  });
  var resEls = PTS.map(function (p) { return el("line", { stroke: "#f87171", "stroke-width": 2, opacity: 0 }, plot); });
  var sqEls = PTS.map(function () { return el("rect", { fill: "rgba(248,113,113,0.25)", stroke: "#f87171", "stroke-width": 1.2, opacity: 0 }, plot); });
  PTS.forEach(function (p) { el("circle", { cx: PX(p[0]), cy: PY(p[1]), r: 7, fill: "#1db584", stroke: "#071510", "stroke-width": 1.5 }, plot); });
  var sseLab = txt(plot, 610, 284, "big", "", "end");

  // Legend of candidate lines.
  var legend = el("g", { opacity: 0 }, plot);
  var legendRows = LINES.map(function (l, i) {
    var g = el("g", {}, legend);
    el("rect", { x: 360, y: 168 + i * 26, width: 14, height: 14, rx: 3, fill: l.color }, g);
    txt(g, 382, 180 + i * 26, "lbl", l.name + "   total " + round1(sse(l)), "start");
    return g;
  });

  // Projection schematic (step 7).
  var proj = el("g", { opacity: 0 }, svg);
  var O = [240, 262], Bt = [360, 80], Pp = [360, 226];
  el("polygon", { points: "130,300 400,300 520,214 250,214", class: "fillA" }, proj);
  txt(proj, 140, 322, "lbl lbl-b", "space of predictions  A x  (column space of A)", "start");
  var bArrow = arrow(proj, "g", 4);
  setLine(bArrow, O[0], O[1], Bt[0], Bt[1]);
  txt(proj, Bt[0] + 10, Bt[1] + 4, "lbl lbl-g", "b  (the data)", "start");
  var pArrow = arrow(proj, "y", 5);
  setLine(pArrow, O[0], O[1], Pp[0], Pp[1]);
  txt(proj, Pp[0] + 12, Pp[1] + 20, "lbl lbl-y", "p = A x̂  (best prediction)", "start");
  var perp = el("line", { class: "dash", stroke: "#f472b6", "stroke-width": 2.2 }, proj);
  setLine(perp, Bt[0], Bt[1], Pp[0], Pp[1]);
  txt(proj, Bt[0] - 12, 150, "lbl lbl-p", "residual ⟂ space", "end");
  el("polyline", { points: (Pp[0] - 14) + "," + Pp[1] + " " + (Pp[0] - 14) + "," + (Pp[1] - 14) + " " + Pp[0] + "," + (Pp[1] - 14), fill: "none", stroke: "#e2b44a", "stroke-width": 2 }, proj);

  var mlPanel = el("g", { opacity: 0 }, svg);
  el("rect", { x: 380, y: 176, width: 240, height: 90, rx: 12, class: "fillG" }, mlPanel);
  txt(mlPanel, 394, 202, "lbl", "linear regression = least squares", "start");
  txt(mlPanel, 394, 232, "mono", "AᵀA x = Aᵀ b", "start");
  txt(mlPanel, 394, 254, "note", "the normal equations", "start");

  function drawLineResiduals(l) {
    PTS.forEach(function (p, i) {
      var yl = l.m * p[0] + l.b;
      setLine(resEls[i], PX(p[0]), PY(p[1]), PX(p[0]), PY(yl));
      var side = Math.abs(p[1] - yl) * 48;
      var top = Math.min(PY(p[1]), PY(yl));
      sqEls[i].setAttribute("x", PX(p[0]));
      sqEls[i].setAttribute("y", top);
      sqEls[i].setAttribute("width", side);
      sqEls[i].setAttribute("height", side);
    });
  }

  function render(index, id) {
    show(plot, id !== "projection-view");
    show(proj, id === "projection-view");
    show(mlPanel, id === "ml-connection");
    lineEls.forEach(function (n) { show(n, false); n.setAttribute("stroke-width", 3); });
    resEls.forEach(function (n) { show(n, false); });
    sqEls.forEach(function (n) { show(n, false); });
    show(legend, false);
    sseLab.textContent = "";
    legendRows.forEach(function (g) { g.setAttribute("opacity", 1); });

    if (id === "candidate-line" || id === "residuals" || id === "square-errors") {
      show(lineEls[0], true);
      drawLineResiduals(LINES[0]);
      if (id !== "candidate-line") resEls.forEach(function (n) { show(n, true); });
      if (id === "square-errors") {
        sqEls.forEach(function (n) { show(n, true); });
        sseLab.textContent = "total squared error = " + round1(sse(LINES[0]));
      }
    } else if (id === "compare-lines") {
      lineEls.forEach(function (n) { show(n, true); });
      show(legend, true);
    } else if (id === "minimum") {
      lineEls.forEach(function (n, i) { show(n, true); if (i !== 2) n.setAttribute("opacity", 0.25); });
      lineEls[2].setAttribute("stroke-width", 5);
      show(legend, true);
      legendRows.forEach(function (g, i) { g.setAttribute("opacity", i === 2 ? 1 : 0.35); });
      sseLab.textContent = "smallest total = " + round1(sse(LINES[2]));
    } else if (id === "ml-connection") {
      show(lineEls[2], true);
      lineEls[2].setAttribute("stroke-width", 5);
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

